// EDUVERSE chunk: simak — generated by build-split.js from canonical bank files. Do not hand-edit.
window.EDUVERSE_BANK_SIMAK = [{"id":"SMMD01","subtes":"Matematika Dasar","soal":"Nilai x yang memenuhi persamaan 3x + 7 = 22 adalah ...","opsi":["5","4","6","7","3"],"kunci":0,"bahas":"Mengurangi kedua ruas dengan 7 menghasilkan 3x sama dengan 15. Membagi kedua ruas dengan 3 menghasilkan x sama dengan 5."},{"id":"SMMD02","subtes":"Matematika Dasar","soal":"Sebuah segitiga memiliki alas 12 cm dan tinggi 9 cm. Luas segitiga tersebut adalah ...","opsi":["48 cm²","54 cm²","60 cm²","108 cm²","45 cm²"],"kunci":1,"bahas":"Luas segitiga dihitung dengan setengah dikali alas dikali tinggi, yaitu setengah dikali 12 dikali 9, hasilnya 54 cm²."},{"id":"SMMD03","subtes":"Matematika Dasar","soal":"Diketahui x + y = 12 dan x − y = 4. Nilai dari x dikali y adalah ...","opsi":["28","30","32","36","24"],"kunci":2,"bahas":"Menjumlahkan persamaan-persamaan tersebut menghasilkan 2x sama dengan 16, sehingga x sama dengan 8 dan y sama dengan 4. Hasil kali x dan y adalah 8 dikali 4, yaitu 32."},{"id":"SMMD04","subtes":"Matematika Dasar","soal":"Diketahui f(x) = 2x² − 3x + 1. Nilai f(3) adalah ...","opsi":["7","8","9","10","12"],"kunci":3,"bahas":"Mengganti x dengan 3 menghasilkan 2 dikali 9 dikurangi 3 dikali 3 ditambah 1, yaitu 18 dikurangi 9 ditambah 1, hasilnya 10."},{"id":"SMBI01","subtes":"Bahasa Indonesia","soal":"Manakah kalimat yang penulisan kata 'di'-nya sudah benar?","opsi":["Buku itu di letakkan di atas meja oleh kakak.","Mereka berlatih dilapangan setiap pagi.","Surat itu di tulis adik kemarin sore.","Anak-anak bermain dikebun belakang rumah.","Ibu menanam bunga di halaman depan rumah."],"kunci":4,"bahas":"Kata 'di' yang menunjukkan tempat ditulis terpisah dari kata berikutnya, sedangkan 'di' sebagai awalan kata kerja pasif ditulis serangkai dengan kata dasarnya. Hanya kalimat tentang ibu menanam bunga yang mengikuti kaidah tersebut: kata 'di' pada frasa tempat ditulis terpisah, dan tidak ada awalan 'di' yang ditulis terpisah."},{"id":"SMBI02","subtes":"Bahasa Indonesia","soal":"Manakah kalimat yang paling efektif?","opsi":["Panitia membagikan bantuan kepada warga yang terdampak banjir.","Panitia membagikan bantuan-bantuan kepada warga-warga yang terdampak banjir yang terjadi kemarin.","Bantuan dibagikan oleh panitia kepada warga yang terdampak banjir adalah bantuan yang sangat baik sekali.","Panitia membagikan bantuan kepada warga yang terdampak banjir yang terdampak banjir.","Para panitia-panitia membagikan bantuan kepada para warga yang terdampak banjir."],"kunci":0,"bahas":"Kalimat yang efektif menyampaikan gagasan secara ringkas dengan susunan yang jelas tanpa pengulangan kata yang tidak perlu dan tanpa penanda penguat ganda. Kalimat tentang panitia membagikan bantuan memenuhi syarat tersebut, sedangkan kalimat lain masih mengandung pengulangan kata, bentuk jamak ganda, atau penguat ganda."},{"id":"SMBI03","subtes":"Bahasa Indonesia","soal":"Di sebuah kampung, warga mendirikan bank sampah untuk mengurangi sampah yang dibuang ke tempat pembuangan akhir. Setiap pekan, warga memilah sampah plastik, kertas, dan kaleng, lalu menukarnya dengan tabungan. Sebagian hasil penjualan sampah dipakai untuk memperbaiki jalan kampung dan membeli bibit tanaman. Kegiatan ini juga membuat warga lebih peduli pada kebersihan lingkungan dan saling bekerja sama. Dengan demikian, bank sampah tidak hanya mengurangi sampah, tetapi juga memberi manfaat ekonomi dan mempererat hubungan antarwarga. Gagasan utama bacaan tersebut adalah ...","opsi":["Bank sampah hanya bermanfaat untuk mengurangi sampah plastik di kampung.","Bank sampah memberi manfaat lingkungan, ekonomi, dan sosial bagi warga kampung.","Warga kampung menukar sampah dengan tabungan setiap pekan.","Hasil penjualan sampah dipakai untuk memperbaiki jalan dan membeli bibit.","Warga kampung menjadi lebih peduli pada kebersihan lingkungan."],"kunci":1,"bahas":"Bacaan menggambarkan bank sampah sebagai kegiatan yang mengurangi sampah, menghasilkan tabungan dan dana untuk keperluan kampung, serta mempererat kerja sama antarwarga. Gagasan yang merangkum seluruh isi bacaan adalah gagasan tentang manfaat lingkungan, ekonomi, dan sosial. Gagasan lain hanya mencakup sebagian isi bacaan."},{"id":"SMBI04","subtes":"Bahasa Indonesia","soal":"Manakah kata yang penulisannya sudah baku?","opsi":["jadual","kwalitas","kualitas","resiko","sistim"],"kunci":2,"bahas":"Bentuk baku kata tersebut adalah kualitas. Bentuk jadual, kwalitas, resiko, dan sistim tidak baku; bentuk bakunya adalah jadwal, kualitas, risiko, dan sistem."},{"id":"SMBING01","subtes":"Bahasa Inggris","soal":"Rani is known for being thrifty. She brings lunch from home, repairs her old shoes instead of buying new ones, and saves part of her allowance every week. The word 'thrifty' in the passage is closest in meaning to ...","opsi":["wasteful with money","careless about spending","generous to strangers","careful with money","lazy about work"],"kunci":3,"bahas":"Perilaku Rani menunjukkan kebiasaan berhemat: membawa bekal, memperbaiki sepatu lama, dan menabung sebagian uang saku. Makna yang sesuai dengan gambaran tersebut adalah hemat dan berhati-hati dalam membelanjakan uang. Makna lain bertentangan dengan gambaran perilaku Rani atau tidak berkaitan dengan cara membelanjakan uang."},{"id":"SMBING02","subtes":"Bahasa Inggris","soal":"By the time we arrived at the cinema, the movie ___.","opsi":["starts","has started","is starting","will start","had started"],"kunci":4,"bahas":"Kejadian film yang mulai terjadi sebelum kejadian lain di masa lampau, yaitu kedatangan kami, sehingga bentuk lampau sempurna yang menyatakan kejadian lebih awal itulah yang tepat. Bentuk waktu kini, bentuk waktu kini sempurna, bentuk sedang, dan bentuk waktu mendatang tidak sesuai dengan rangkaian waktu lampau dalam kalimat tersebut."},{"id":"SMBING03","subtes":"Bahasa Inggris","soal":"In a small town, a group of volunteers opened a bicycle workshop every Saturday. Residents could bring broken bicycles and learn to fix flat tires, loose chains, and squeaky brakes with help from experienced mechanics. The volunteers did not charge for the lessons, but they asked visitors to help the next person once they had learned a simple repair. Over time, more residents began cycling to work and school, and fewer bicycles were thrown away. The workshop became a place where people learned useful skills, saved money, and met their neighbours. What is the main idea of the passage?","opsi":["A free bicycle workshop helps residents learn repair skills, save money, and build community ties.","All residents in the town ride bicycles to work and school every day.","Experienced mechanics should repair every bicycle without teaching the owners.","Bicycle workshops are the only way to reduce waste in a small town.","Flat tires and loose chains are the most difficult bicycle problems to fix."],"kunci":0,"bahas":"Bacaan menceritakan lokakarya sepeda gratis tempat warga belajar memperbaiki sepeda, menghemat uang, mengurangi sepeda yang dibuang, dan bertemu tetangga. Gagasan utama merangkum seluruh manfaat tersebut. Gagasan lain melebih-lebihkan isi bacaan, bertentangan dengan cara kerja lokakarya, atau hanya menyebut satu rincian."},{"id":"SMBING04","subtes":"Bahasa Inggris","soal":"The scientist checked her measurements three times to make sure the results were accurate. The word 'accurate' is closest in meaning to ...","opsi":["careless and rough","correct and exact","quick and hurried","expensive and rare","simple and short"],"kunci":1,"bahas":"Memeriksa pengukuran berulang kali bertujuan memastikan hasil pengukuran benar dan tepat, sesuai dengan keadaan yang sebenarnya. Makna tersebut sesuai dengan gagasan benar dan tepat. Makna lain bertentangan dengan tujuan pemeriksaan berulang atau tidak berkaitan dengan kebenaran hasil pengukuran."},{"id":"SMV01","subtes":"Verbal","soal":"Kata 'cermat' memiliki makna yang paling dekat dengan kata ...","opsi":["ceroboh","tergesa-gesa","teliti","lamban","ragu-ragu"],"kunci":2,"bahas":"Cermat berarti berhati-hati dan penuh ketelitian dalam melakukan sesuatu, sehingga makna yang paling dekat adalah teliti. Kata lain berarti ceroboh, terburu-buru, lamban, atau ragu, yang tidak sama dengan makna cermat."},{"id":"SMV02","subtes":"Verbal","soal":"Lawan kata dari 'loyal' adalah ...","opsi":["setia","patuh","jujur","berkhianat","tekun"],"kunci":3,"bahas":"Loyal berarti setia dan patuh kepada pihak yang dilayani. Lawan maknanya adalah berkhianat, yaitu tidak setia dan mengingkari kepercayaan. Kata lain memiliki makna yang sejalan dengan loyal atau tidak berlawanan dengannya."},{"id":"SMV03","subtes":"Verbal","soal":"Lengkapilah analogi berikut: Dokter : Pasien = ... Pasangan kata manakah yang memiliki hubungan yang sama dengan pasangan kata tersebut?","opsi":["Koki : Dapur","Petani : Sawah","Pilot : Pesawat","Penulis : Buku","Guru : Murid"],"kunci":4,"bahas":"Dokter adalah pihak yang melayani pasien sebagai pihak yang dilayani. Hubungan yang sama terdapat pada guru sebagai pihak yang mengajar murid sebagai pihak yang diajar. Pasangan lain menunjukkan hubungan orang dengan tempat bekerja, orang dengan alat yang dipakai, atau pencipta dengan karya yang dihasilkan."},{"id":"SMV04","subtes":"Verbal","soal":"Sebuah toko buku kecil mulai mengadakan malam baca setiap Jumat. Pengunjung boleh membaca buku apa pun tanpa membeli, dan pemilik toko menyediakan teh hangat tanpa biaya. Dalam tiga bulan, jumlah pengunjung pada malam baca bertambah tiga kali lipat, dan banyak pengunjung yang akhirnya membeli buku yang mereka baca. Pemilik toko juga mencatat bahwa pengunjung mulai saling mengenal dan membentuk kelompok diskusi. Berdasarkan bacaan tersebut, dapat disimpulkan bahwa ...","opsi":["Malam baca tanpa kewajiban membeli dapat menarik pengunjung dan menumbuhkan penjualan serta kebersamaan.","Semua pengunjung toko buku selalu membeli buku setiap kali datang.","Teh hangat gratis adalah satu-satunya alasan pengunjung datang ke toko buku.","Toko buku kecil tidak dapat bertahan tanpa mengadakan malam baca.","Kelompok diskusi hanya dibentuk oleh pengunjung yang membeli buku paling banyak."],"kunci":0,"bahas":"Bacaan menyatakan jumlah pengunjung bertambah, banyak pengunjung akhirnya membeli buku yang dibaca, dan pengunjung mulai saling mengenal serta membentuk kelompok diskusi. Simpulan yang didukung oleh seluruh keterangan tersebut adalah simpulan tentang malam baca yang menarik pengunjung dan menumbuhkan penjualan serta kebersamaan. Simpulan lain melebih-lebihkan isi bacaan atau menambahkan keterangan yang tidak dinyatakan."},{"id":"SMV05","subtes":"Verbal","soal":"Kata 'mendadak' memiliki makna yang paling dekat dengan kata ...","opsi":["perlahan","tiba-tiba","teratur","direncanakan","bertahap"],"kunci":1,"bahas":"Mendadak berarti terjadi secara tiba-tiba tanpa diduga sebelumnya. Makna yang paling dekat adalah tiba-tiba. Kata lain berarti perlahan, teratur, direncanakan, atau bertahap, yang bertentangan dengan makna mendadak."},{"id":"SMV06","subtes":"Verbal","soal":"Lawan kata dari 'abstrak' adalah ...","opsi":["rumit","samar","konkret","luas","dalam"],"kunci":2,"bahas":"Abstrak berarti tidak berwujud dan hanya ada dalam pikiran. Lawan maknanya adalah konkret, yaitu nyata dan dapat ditangkap oleh indra. Kata lain berarti rumit, samar, luas, atau dalam, yang tidak berlawanan dengan makna abstrak."},{"id":"SMV07","subtes":"Verbal","soal":"Lengkapilah analogi berikut: Matahari : Siang = ... Pasangan kata manakah yang memiliki hubungan yang sama dengan pasangan kata tersebut?","opsi":["Bintang : Langit","Hujan : Payung","Api : Panas","Bulan : Malam","Laut : Ombak"],"kunci":3,"bahas":"Matahari adalah benda langit yang menjadi penanda waktu siang. Hubungan yang sama terdapat pada bulan sebagai benda langit yang menjadi penanda waktu malam. Pasangan lain menunjukkan hubungan benda dengan tempatnya, benda dengan alat pelindungnya, benda dengan sifat yang ditimbulkannya, atau benda dengan bagiannya."},{"id":"SMK01","subtes":"Kuantitatif","soal":"15% dari 240 adalah ...","opsi":["30","32","34","38","36"],"kunci":4,"bahas":"15 persen dari 240 dihitung dengan 15 dibagi 100 dikali 240, hasilnya 36."},{"id":"SMK02","subtes":"Kuantitatif","soal":"Perhatikan barisan bilangan berikut: 3, 6, 11, 18, 27, ... Bilangan berikutnya dalam barisan tersebut adalah ...","opsi":["38","36","40","37","39"],"kunci":0,"bahas":"Selisih antarbilangan yang berurutan adalah 3, 5, 7, dan 9, sehingga selisih bertambah 2 pada setiap langkah. Selisih berikutnya adalah 11, sehingga bilangan berikutnya adalah 27 ditambah 11, yaitu 38."},{"id":"SMK03","subtes":"Kuantitatif","soal":"Perbandingan uang Ani dan Budi adalah 3 : 5. Jika jumlah uang mereka adalah Rp160.000, selisih uang mereka adalah ...","opsi":["Rp30.000","Rp40.000","Rp50.000","Rp20.000","Rp60.000"],"kunci":1,"bahas":"Jumlah bagian perbandingan adalah 8, sehingga satu bagian bernilai Rp160.000 dibagi 8, yaitu Rp20.000. Selisih perbandingan adalah 2 bagian, sehingga selisih uang mereka adalah 2 dikali Rp20.000, yaitu Rp40.000. Sebagai pemeriksaan, uang Ani adalah Rp60.000 dan uang Budi adalah Rp100.000."},{"id":"SMK04","subtes":"Kuantitatif","soal":"Harga sebuah tas adalah Rp80.000. Harga tas tersebut naik 25%. Harga tas setelah naik adalah ...","opsi":["Rp95.000","Rp98.000","Rp100.000","Rp105.000","Rp110.000"],"kunci":2,"bahas":"Kenaikan 25 persen dari Rp80.000 adalah Rp20.000. Harga setelah naik adalah Rp80.000 ditambah Rp20.000, yaitu Rp100.000."},{"id":"SMK05","subtes":"Kuantitatif","soal":"Rata-rata nilai 5 siswa adalah 70. Seorang siswa dengan nilai 88 bergabung ke dalam kelompok tersebut. Rata-rata nilai keenam siswa tersebut adalah ...","opsi":["71","72","72,5","73","74"],"kunci":3,"bahas":"Jumlah nilai 5 siswa adalah 5 dikali 70, yaitu 350. Setelah ditambah 88, jumlah nilai menjadi 438. Rata-rata 6 siswa adalah 438 dibagi 6, yaitu 73."},{"id":"SMK06","subtes":"Kuantitatif","soal":"Perhatikan barisan bilangan berikut: 1, 4, 9, 16, 25, ... Bilangan berikutnya dalam barisan tersebut adalah ...","opsi":["30","32","34","35","36"],"kunci":4,"bahas":"Setiap suku merupakan kuadrat bilangan berurutan: 1 kuadrat sama dengan 1, 2 kuadrat sama dengan 4, 3 kuadrat sama dengan 9, 4 kuadrat sama dengan 16, dan 5 kuadrat sama dengan 25. Suku berikutnya adalah 6 kuadrat, yaitu 36."},{"id":"SMK07","subtes":"Kuantitatif","soal":"Sebuah tangki dapat dikosongkan oleh 5 pompa air yang identik dalam 8 jam. Jika jumlah pompa yang bekerja ditambah menjadi 8 pompa dengan kemampuan yang sama, tangki tersebut dapat dikosongkan dalam ...","opsi":["5 jam","6 jam","4 jam","7 jam","3 jam"],"kunci":0,"bahas":"Volume tangki yang sama memerlukan 5 dikali 8, yaitu 40 jam-pompa. Dengan 8 pompa, waktu yang diperlukan adalah 40 dibagi 8, yaitu 5 jam."},{"id":"SMK08","subtes":"Kuantitatif","soal":"Hasil dari (12 + 8) × 3 − 20 adalah ...","opsi":["36","40","44","30","50"],"kunci":1,"bahas":"Penjumlahan di dalam kurung menghasilkan 20. Perkalian 20 dengan 3 menghasilkan 60. Pengurangan 60 dengan 20 menghasilkan 40."},{"id":"SMK09","subtes":"Kuantitatif","soal":"Sebuah mobil menempuh jarak 120 km dalam waktu 2 jam dengan kecepatan tetap. Kecepatan mobil tersebut adalah ...","opsi":["50 km/jam","55 km/jam","60 km/jam","65 km/jam","70 km/jam"],"kunci":2,"bahas":"Kecepatan dihitung dengan jarak dibagi waktu, yaitu 120 km dibagi 2 jam, hasilnya 60 km per jam."},{"id":"SML01","subtes":"Logika","soal":"Perhatikan dua premis berikut. Premis 1: Semua buku di rak merah adalah buku cerita. Premis 2: Semua buku cerita memakai sampul bergambar. Manakah kesimpulan yang tepat berdasarkan kedua premis tersebut?","opsi":["Semua buku cerita berada di rak merah.","Sebagian buku di rak merah tidak memakai sampul bergambar.","Semua buku yang memakai sampul bergambar berada di rak merah.","Semua buku di rak merah memakai sampul bergambar.","Tidak ada buku di rak merah yang memakai sampul bergambar."],"kunci":3,"bahas":"Semua buku di rak merah termasuk buku cerita, dan semua buku cerita memakai sampul bergambar, sehingga semua buku di rak merah juga memakai sampul bergambar. Kesimpulan lain membalik hubungan yang dinyatakan premis, membatasi kesimpulan pada sebagian, atau bertentangan dengan premis."},{"id":"SML02","subtes":"Logika","soal":"Semua anggota klub renang dapat berenang. Rudi tidak dapat berenang. Manakah kesimpulan yang tepat?","opsi":["Rudi adalah anggota klub renang.","Rudi pernah menjadi anggota klub renang.","Semua orang yang tidak dapat berenang adalah anggota klub renang.","Rudi akan segera menjadi anggota klub renang.","Rudi bukan anggota klub renang."],"kunci":4,"bahas":"Kemampuan berenang merupakan syarat bagi anggota klub renang. Rudi tidak memiliki kemampuan tersebut, sehingga Rudi tidak termasuk anggota klub renang. Kesimpulan lain bertentangan dengan keterangan yang diberikan atau menambahkan keterangan tentang masa lalu dan masa depan yang tidak dinyatakan."},{"id":"SML03","subtes":"Logika","soal":"Andi lebih tinggi daripada Budi. Budi lebih tinggi daripada Candra. Dina lebih tinggi daripada Andi. Siapakah yang paling tinggi di antara mereka?","opsi":["Dina","Andi","Budi","Candra","Tidak dapat ditentukan"],"kunci":0,"bahas":"Urutan tinggi dari yang paling tinggi adalah Dina, lalu Andi, lalu Budi, lalu Candra. Dina berada di atas Andi, Andi berada di atas Budi, dan Budi berada di atas Candra, sehingga yang paling tinggi adalah Dina."},{"id":"SML04","subtes":"Logika","soal":"Empat siswa, yaitu P, Q, R, dan S, antre pada posisi 1 (paling depan) sampai posisi 4 (paling belakang). Diketahui: P berada tepat di depan Q; S berada di posisi paling belakang; R tidak berada di posisi paling depan. Manakah pernyataan yang pasti benar?","opsi":["Q berada di posisi paling depan.","P berada di posisi paling depan.","R berada tepat di depan Q.","Q berada di posisi ketiga.","R berada di posisi paling belakang."],"kunci":1,"bahas":"S menempati posisi paling belakang. Pasangan P dan Q yang berurutan hanya dapat menempati posisi 1 dan 2, karena pasangan pada posisi 2 dan 3 akan menempatkan R pada posisi paling depan, yang dilarang oleh syarat. Susunan yang memenuhi semua syarat hanya P, Q, R, dan S secara berurutan dari depan ke belakang, sehingga P berada di posisi paling depan."},{"id":"SML05","subtes":"Logika","soal":"Jika hari hujan, jalanan menjadi basah. Hari ini jalanan tidak basah. Manakah kesimpulan yang tepat?","opsi":["Hari ini hujan.","Jalanan menjadi basah karena hujan.","Hari ini tidak hujan.","Hujan menyebabkan jalanan selalu basah setiap hari.","Jalanan tidak pernah basah."],"kunci":2,"bahas":"Jalanan yang basah merupakan akibat dari hujan. Jalanan yang tidak basah menunjukkan akibat tersebut tidak terjadi, sehingga penyebabnya, yaitu hujan, juga tidak terjadi pada hari itu. Kesimpulan lain menyatakan hujan terjadi, menyatakan akibat yang bertentangan dengan keterangan, atau melebih-lebihkan keterangan menjadi berlaku setiap hari dan selamanya."},{"id":"SML06","subtes":"Logika","soal":"Perhatikan barisan bilangan berikut: 4, 11, 25, 53, ... Bilangan berikutnya dalam barisan tersebut adalah ...","opsi":["105","106","107","109","111"],"kunci":3,"bahas":"Setiap suku diperoleh dengan menggandakan suku sebelumnya lalu menambah 3: 4 dikali 2 ditambah 3 sama dengan 11, 11 dikali 2 ditambah 3 sama dengan 25, dan 25 dikali 2 ditambah 3 sama dengan 53. Suku berikutnya adalah 53 dikali 2 ditambah 3, yaitu 109."},{"id":"SML07","subtes":"Logika","soal":"Semua karyawan yang lembur mendapat makan malam. Sebagian karyawan lembur hari ini. Manakah kesimpulan yang tepat?","opsi":["Semua karyawan mendapat makan malam hari ini.","Tidak ada karyawan yang mendapat makan malam hari ini.","Semua karyawan lembur hari ini.","Karyawan yang tidak lembur juga mendapat makan malam hari ini.","Sebagian karyawan mendapat makan malam hari ini."],"kunci":4,"bahas":"Karyawan yang lembur hari ini termasuk sebagian karyawan, dan setiap karyawan yang lembur mendapat makan malam, sehingga sebagian karyawan mendapat makan malam hari ini. Kesimpulan lain menyatakan seluruh karyawan, menyatakan tidak ada, atau menambahkan keterangan tentang karyawan yang tidak lembur yang tidak dinyatakan."}];
